def train_val_test_split(n, val, test, seed):
    if min(val, test) < 0 or val + test >= n:
        raise ValueError('Số mẫu không hợp lệ.')
    order = np.random.default_rng(seed).permutation(n)
    end = n - val - test
    return order[:end], order[end:end+val], order[end+val:]

