exercises.solution:
def grad_mse(X,y,w):
    return (2/len(y)) * (X.T @ (X @ w - y))

def numerical_grad(loss,w,eps=1e-6):
    eye = np.eye(len(w))
    return np.array([(loss(w+eps*v)-loss(w-eps*v))/(2*eps) for v in eye])

def gradient_descent(X,y,w,lr,steps):
    w=np.array(w,dtype=float,copy=True)
    for _ in range(steps):
        w-=lr*grad_mse(X,y,w)
    return w

