def fit_ridge(X,y,lam):
    A=np.column_stack((np.ones(len(X)),X))
    penalty=np.diag(np.r_[0.,np.ones(X.shape[1])])
    return np.linalg.lstsq(np.vstack([A,np.sqrt(lam)*penalty]),np.r_[y,np.zeros(A.shape[1])],rcond=None)[0]

